    int maxChunksToSorted(vector<int>& arr) {
        vector<int> st;
        for (int x : arr) {
            if (st.empty() || x >= st.back()) {
                st.push_back(x);
            } else {
                int curMax = st.back();
                while (!st.empty() && st.back() > x) {
                    st.pop_back();
