            }
        }
        return st.size();
    }
};

class Solution {
    public int maxChunksToSorted(int[] arr) {
        Deque<Integer> st = new ArrayDeque<>();
        for (int x : arr) {
            if (st.isEmpty() || x >= st.peek()) {
                st.push(x);
            } else {
                int curMax = st.peek();
                while (!st.isEmpty() && st.peek() > x) {
                    st.pop();
                }
                st.push(curMax);
            }
        }
        return st.size();
    }
}

